func render18(_ s: L18) -> NSImage {
    let img = NSImage(size: NSSize(width: SW18, height: PH18))
    img.lockFocus()
    NSColor.white.setFill()
    NSRect(x: 0, y: 0, width: SW18, height: PH18).fill()

    let left = NSRect(x: 0, y: 0, width: PW18, height: PH18)
    let right = NSRect(x: PW18, y: 0, width: PW18, height: PH18)
    let gap: CGFloat = 18
    let m: CGFloat = 40

    switch s.kind {
    case .fullBleedCross(let a):
        drawPhoto(a[0], in: NSRect(x: 0, y: 0, width: SW18, height: PH18), fit: .cover)
        // thin gutter line
        NSColor(white: 1, alpha: 0.15).setFill()
        NSRect(x: PW18 - 1, y: 0, width: 2, height: PH18).fill()
        label(a[0], at: NSPoint(x: 20, y: 20))
    case .fullBleedPair(let a, let b):
        drawPhoto(a, in: left, fit: .cover)
        drawPhoto(b, in: right, fit: .cover)
        label(a, at: NSPoint(x: 20, y: 20))
        label(b, at: NSPoint(x: PW18 + 20, y: 20))
    case .heroLeftSmallsRight(let hero, let smalls):
        // left ~70% of LEFT page? Spec: one image 70% of page, two small 30%. Across spread: left page = hero full bleed, right = two stacked
        drawPhoto(hero, in: left, fit: .cover)
        if smalls.count == 1 {
            let r = right.insetBy(dx: m, dy: m)
            drawPhoto(smalls[0], in: r, fit: .cover)
            label(smalls[0], at: NSPoint(x: r.minX + 8, y: r.minY + 8))
        } else {
            let h = (PH18 - m * 2 - gap) / 2
            let top = NSRect(x: PW18 + m, y: PH18 - m - h, width: PW18 - m * 2, height: h)
            let bot = NSRect(x: PW18 + m, y: m, width: PW18 - m * 2, height: h)
            drawPhoto(smalls[0], in: top, fit: .cover)
            drawPhoto(smalls[1], in: bot, fit: .cover)
            label(smalls[0], at: NSPoint(x: top.minX + 8, y: top.minY + 8))
            label(smalls[1], at: NSPoint(x: bot.minX + 8, y: bot.minY + 8))
        }
        label(hero, at: NSPoint(x: 20, y: 20))
    case .smallsLeftHeroRight(let smalls, let hero):
        let h = (PH18 - m * 2 - gap) / 2
        let top = NSRect(x: m, y: PH18 - m - h, width: PW18 - m * 2, height: h)
        let bot = NSRect(x: m, y: m, width: PW18 - m * 2, height: h)
        drawPhoto(smalls[0], in: top, fit: .cover)
        drawPhoto(smalls[1], in: bot, fit: .cover)
        drawPhoto(hero, in: right, fit: .cover)
        label(smalls[0], at: NSPoint(x: top.minX + 8, y: top.minY + 8))
        label(smalls[1], at: NSPoint(x: bot.minX + 8, y: bot.minY + 8))
        label(hero, at: NSPoint(x: PW18 + 20, y: 20))
    case .twoH(let a, let b):
        let lr = left.insetBy(dx: m, dy: m)
        let rr = right.insetBy(dx: m, dy: m)
        drawPhoto(a, in: lr, fit: .cover)
        drawPhoto(b, in: rr, fit: .cover)
        label(a, at: NSPoint(x: lr.minX + 8, y: lr.minY + 8))
        label(b, at: NSPoint(x: rr.minX + 8, y: rr.minY + 8))
    default:
        break
    }

    let title = String(format: "%02d  %@", s.no, s.scene) as NSString
    let ta: [NSAttributedString.Key: Any] = [
        .font: NSFont.systemFont(ofSize: 28, weight: .medium),
        .foregroundColor: NSColor.white,
        .backgroundColor: NSColor(white: 0, alpha: 0.35)
    ]
    title.draw(at: NSPoint(x: 16, y: PH18 - 44), withAttributes: ta)
    img.unlockFocus()
    return img
}

