    NSColor(white: 0.93, alpha: 1).setFill()
    NSRect(x:0,y:0,width:ow,height:oh).fill()
    for (i, t) in thumbs.enumerated() {
        let y = oh - 20 - CGFloat(i + 1) * (th + gap) + gap
        t.draw(in: NSRect(x: 20, y: y, width: tw, height: th))
    }
    o.unlockFocus()
    saveJPEG(o, path: path, q: 0.8)
}
