func path(_ id: String) -> String { SRC + "/" + id + ".jpg" }

func loadCG(_ id: String) -> (CGImage, CGFloat, CGFloat)? {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path(id)) as CFURL, nil),
          let cg = CGImageSourceCreateImageAtIndex(src, 0, [kCGImageSourceShouldCache: true] as CFDictionary) else { return nil }
    return (cg, CGFloat(cg.width), CGFloat(cg.height))
}

func saveJPEG(_ img: NSImage, to out: String, q: CGFloat = 0.88) {
    guard let tiff = img.tiffRepresentation,
          let rep = NSBitmapImageRep(data: tiff),
          let data = rep.representation(using: .jpeg, properties: [.compressionFactor: q]) else {
        fputs("save fail \(out)\n", stderr); exit(1)
    }
    try! data.write(to: URL(fileURLWithPath: out))
