import Foundation
import AppKit
import Vision
import ImageIO

/**
 v4 — content-first, classic wedding album rules:
 - Design the SPREAD (two pages) as one unit
 - Same scene + color temperature on a spread
 - One visual weight per spread (hero + support of same moment)
 - Few layout types reused
 - Cross-bleed only for true wide heroes; subjects off gutter
 - Vertical stays vertical (two V side-by-side), never forced to landscape crop
 - Full bleed (user preference) but pairing is intentional
 Refs: Wedding Book Press spread narrative; 同色系跨页; Amelia Lyon minimal layouts
 */

let SRC = "/Users/mac/Desktop/个人/26.7.16武雅茹&闫泽群黑标四套【阿帅 佳佳】/婚纱照"
