func render18(_ s: S18) -> NSImage {
    let img = NSImage(size: NSSize(width: SW, height: PH))
    img.lockFocus()
    NSColor.black.setFill()
    NSRect(x: 0, y: 0, width: SW, height: PH).fill()
    let left = NSRect(x: 0, y: 0, width: PW, height: PH)
    let right = NSRect(x: PW, y: 0, width: PW, height: PH)

    switch s.kind {
    case .cross(let a):
        guard let (cg, _, _) = loadCG(a) else { break }
        let (sx, _) = subjectCenter(cg: cg)
        let bias = sx < 0.5 ? SW * 0.30 : SW * 0.70
        drawCover(a, in: NSRect(x: 0, y: 0, width: SW, height: PH), biasX: bias)
        badge(a, NSPoint(x: 10, y: 8))
    case .pairHH(let a, let b):
        drawCover(a, in: left)
        drawCover(b, in: right)
        badge(a, NSPoint(x: 10, y: 8))
        badge(b, NSPoint(x: PW + 10, y: 8))
    case .heroH_twoV(let h, let v1, let v2):
        drawCover(h, in: left)
        let half = PW / 2
        drawPortraitSlot(v1, in: NSRect(x: PW, y: 0, width: half, height: PH))
        drawPortraitSlot(v2, in: NSRect(x: PW + half, y: 0, width: half, height: PH))
        badge(h, NSPoint(x: 10, y: 8))
        badge(v1, NSPoint(x: PW + 6, y: 8))
        badge(v2, NSPoint(x: PW + half + 6, y: 8))
    }
    cap(String(format: "%02d  %@", s.no, s.scene), h: PH)
    img.unlockFocus()
    return img
}

