func stack(_ thumbs: [NSImage], tw: CGFloat, th: CGFloat, path: String) {
    let gap: CGFloat = 10
    let ow = tw + 40
    let oh = 24 + CGFloat(thumbs.count) * (th + gap)
    let o = NSImage(size: NSSize(width: ow, height: oh))
