func jpg(_ id: String) -> String { SRC + "/" + id + ".jpg" }
func exists(_ id: String) -> Bool { FileManager.default.fileExists(atPath: jpg(id)) }

func loadCG(_ id: String) -> (CGImage, CGFloat, CGFloat)? {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: jpg(id)) as CFURL, nil),
          let cg = CGImageSourceCreateImageAtIndex(src, 0, [kCGImageSourceShouldCache: true] as CFDictionary)
    else { return nil }
    return (cg, CGFloat(cg.width), CGFloat(cg.height))
}

enum Ori { case H, V }
func ori(_ id: String) -> Ori {
    guard let (_, w, h) = loadCG(id) else { return .H }
    return w >= h * 1.05 ? .H : .V
}

func subjectCenter(cg: CGImage) -> (CGFloat, CGFloat) {
    let req = VNDetectFaceRectanglesRequest()
    try? VNImageRequestHandler(cgImage: cg, options: [:]).perform([req])
    let faces = req.results ?? []
    if faces.isEmpty { return (0.5, 0.40) }
    var sx: CGFloat = 0, sy: CGFloat = 0, w: CGFloat = 0
    for f in faces {
        let a = f.boundingBox.width * f.boundingBox.height
        sx += f.boundingBox.midX * a
        sy += f.boundingBox.midY * a
        w += a
    }
    return (sx / w, sy / w)
}

func saveJPEG(_ img: NSImage, to path: String, q: CGFloat = 0.88) {
    guard let tiff = img.tiffRepresentation,
          let rep = NSBitmapImageRep(data: tiff),
          let data = rep.representation(using: .jpeg, properties: [.compressionFactor: q]) else {
        fputs("save fail \(path)\n", stderr); exit(1)
    }
    try! data.write(to: URL(fileURLWithPath: path))
}

func drawCover(_ id: String, in dest: NSRect, biasX: CGFloat? = nil) {
    guard let (cg, pw, ph) = loadCG(id) else { return }
    let (sx, sy) = subjectCenter(cg: cg)
    let scale = max(dest.width / pw, dest.height / ph)
    let dw = pw * scale, dh = ph * scale
    let tx = biasX ?? dest.midX
    var ox = tx - sx * pw * scale
    var oy = dest.midY - sy * ph * scale
    ox = min(max(ox, dest.maxX - dw), dest.minX)
    oy = min(max(oy, dest.maxY - dh), dest.minY)
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: dest).addClip()
    NSImage(cgImage: cg, size: NSSize(width: pw, height: ph))
        .draw(in: NSRect(x: ox, y: oy, width: dw, height: dh), from: .zero, operation: .copy, fraction: 1)
    NSGraphicsContext.current?.cgContext.restoreGState()
}

func drawPortraitSlot(_ id: String, in dest: NSRect) {
    guard let (cg, pw, ph) = loadCG(id) else { return }
    let (sx, sy) = subjectCenter(cg: cg)
    let scale = max(dest.height / ph, dest.width / pw)
    let dw = pw * scale, dh = ph * scale
    var ox = dest.midX - sx * pw * scale
    var oy = dest.midY - sy * ph * scale
    ox = min(max(ox, dest.maxX - dw), dest.minX)
    oy = min(max(oy, dest.maxY - dh), dest.minY)
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: dest).addClip()
    NSImage(cgImage: cg, size: NSSize(width: pw, height: ph))
        .draw(in: NSRect(x: ox, y: oy, width: dw, height: dh), from: .zero, operation: .copy, fraction: 1)
    NSGraphicsContext.current?.cgContext.restoreGState()
}

