    var ox = dest.midX - sx * pw * scale, oy = dest.midY - sy * ph * scale
    ox = min(max(ox, dest.maxX - dw), dest.minX)
    oy = min(max(oy, dest.maxY - dh), dest.minY)
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: dest).addClip()
    NSImage(cgImage: cg, size: NSSize(width: pw, height: ph)).draw(in: NSRect(x: ox, y: oy, width: dw, height: dh), from: .zero, operation: .copy, fraction: 1)
    NSGraphicsContext.current?.cgContext.restoreGState()
}
func badge(_ t: String, _ p: NSPoint) {
    (t as NSString).draw(at: p, withAttributes: [.font: NSFont.monospacedSystemFont(ofSize: 11, weight: .semibold), .foregroundColor: NSColor.white, .backgroundColor: NSColor(white: 0, alpha: 0.45)])
}
func cap(_ t: String, h: CGFloat) {
    (t as NSString).draw(at: NSPoint(x: 10, y: h - 28), withAttributes: [.font: NSFont.systemFont(ofSize: 16, weight: .medium), .foregroundColor: NSColor.white, .backgroundColor: NSColor(white: 0, alpha: 0.4)])
