func drawStack2(_ top: String, _ bot: String, in page: NSRect) {
    let half = page.height / 2
    drawCover(top, in: NSRect(x: page.minX, y: page.minY + half, width: page.width, height: half))
    drawCover(bot, in: NSRect(x: page.minX, y: page.minY, width: page.width, height: half))
}
func drawOnePlusTwo(_ top: String, _ bl: String, _ br: String, in page: NSRect) {
    let halfH = page.height / 2
    let halfW = page.width / 2
    drawCover(top, in: NSRect(x: page.minX, y: page.minY + halfH, width: page.width, height: halfH))
    drawCover(bl, in: NSRect(x: page.minX, y: page.minY, width: halfW, height: halfH))
    drawCover(br, in: NSRect(x: page.minX + halfW, y: page.minY, width: halfW, height: halfH))
}

func render18(_ s: S18) -> NSImage {
    let img = NSImage(size: NSSize(width: SW, height: PH))
    img.lockFocus(); NSColor.black.setFill(); NSRect(x: 0, y: 0, width: SW, height: PH).fill()
    let left = NSRect(x: 0, y: 0, width: PW, height: PH)
    let right = NSRect(x: PW, y: 0, width: PW, height: PH)
    switch s.kind {
    case .cross(let a):
        let (cg, _, _) = loadCG(a)!
        let (sx, _) = subjectCenter(cg: cg)
        drawCover(a, in: NSRect(x: 0, y: 0, width: SW, height: PH), biasX: sx < 0.5 ? SW * 0.30 : SW * 0.70)
        badge(a, NSPoint(x: 10, y: 8))
    case .pairHH(let a, let b):
        drawCover(a, in: left); drawCover(b, in: right)
        badge(a, NSPoint(x: 10, y: 8)); badge(b, NSPoint(x: PW + 10, y: 8))
    case .heroH_twoV(let h, let v1, let v2):
        drawCover(h, in: left)
        let half = PW / 2
        drawPortraitSlot(v1, in: NSRect(x: PW, y: 0, width: half, height: PH))
        drawPortraitSlot(v2, in: NSRect(x: PW + half, y: 0, width: half, height: PH))
        badge(h, NSPoint(x: 10, y: 8)); badge(v1, NSPoint(x: PW + 6, y: 8)); badge(v2, NSPoint(x: PW + half + 6, y: 8))
    case .heroH_twoH(let h, let a, let b):
        drawCover(h, in: left)
        drawStack2(a, b, in: right)
        badge(h, NSPoint(x: 10, y: 8)); badge(a, NSPoint(x: PW + 6, y: PH/2 + 6)); badge(b, NSPoint(x: PW + 6, y: 8))
    case .twoH_heroH(let a, let b, let h):
        drawStack2(a, b, in: left)
        drawCover(h, in: right)
        badge(a, NSPoint(x: 6, y: PH/2 + 6)); badge(b, NSPoint(x: 6, y: 8)); badge(h, NSPoint(x: PW + 10, y: 8))
    case .heroH_threeH(let h, let t, let bl, let br):
        drawCover(h, in: left)
        drawOnePlusTwo(t, bl, br, in: right)
        badge(h, NSPoint(x: 10, y: 8)); badge(t, NSPoint(x: PW + 6, y: PH/2 + 6))
        badge(bl, NSPoint(x: PW + 6, y: 8)); badge(br, NSPoint(x: PW + PW/2 + 6, y: 8))
    case .threeH_heroH(let t, let bl, let br, let h):
        drawOnePlusTwo(t, bl, br, in: left)
        drawCover(h, in: right)
        badge(t, NSPoint(x: 6, y: PH/2 + 6)); badge(bl, NSPoint(x: 6, y: 8))
        badge(br, NSPoint(x: PW/2 + 6, y: 8)); badge(h, NSPoint(x: PW + 10, y: 8))
    }
    cap(String(format: "%02d  %@  %@", s.no, s.scene, label18(s.kind)), h: PH)
    img.unlockFocus(); return img
}

func render12(_ s: S12) -> NSImage {
    let img = NSImage(size: NSSize(width: S, height: P))
    img.lockFocus(); NSColor.black.setFill(); NSRect(x: 0, y: 0, width: S, height: P).fill()
    let left = NSRect(x: 0, y: 0, width: P, height: P)
    let right = NSRect(x: P, y: 0, width: P, height: P)
    switch s.kind {
    case .twin(let a, let b):
        drawCover(a, in: left); drawCover(b, in: right)
        badge(a, NSPoint(x: 8, y: 8)); badge(b, NSPoint(x: P + 8, y: 8))
    case .fourV(let a, let b, let c, let d):
        let half = P / 2
        drawPortraitSlot(a, in: NSRect(x: 0, y: 0, width: half, height: P))
        drawPortraitSlot(b, in: NSRect(x: half, y: 0, width: half, height: P))
        drawPortraitSlot(c, in: NSRect(x: P, y: 0, width: half, height: P))
        drawPortraitSlot(d, in: NSRect(x: P + half, y: 0, width: half, height: P))
    case .hero_two(let h, let a, let b):
        drawCover(h, in: left)
        drawStack2(a, b, in: right)
        badge(h, NSPoint(x: 8, y: 8)); badge(a, NSPoint(x: P + 6, y: P/2 + 6)); badge(b, NSPoint(x: P + 6, y: 8))
    case .two_hero(let a, let b, let h):
        drawStack2(a, b, in: left)
        drawCover(h, in: right)
        badge(a, NSPoint(x: 6, y: P/2 + 6)); badge(b, NSPoint(x: 6, y: 8)); badge(h, NSPoint(x: P + 8, y: 8))
    case .hero_three(let h, let t, let bl, let br):
        drawCover(h, in: left)
        drawOnePlusTwo(t, bl, br, in: right)
        badge(h, NSPoint(x: 8, y: 8)); badge(t, NSPoint(x: P + 6, y: P/2 + 6))
        badge(bl, NSPoint(x: P + 6, y: 8)); badge(br, NSPoint(x: P + P/2 + 6, y: 8))
    case .three_hero(let t, let bl, let br, let h):
        drawOnePlusTwo(t, bl, br, in: left)
        drawCover(h, in: right)
        badge(t, NSPoint(x: 6, y: P/2 + 6)); badge(bl, NSPoint(x: 6, y: 8))
        badge(br, NSPoint(x: P/2 + 6, y: 8)); badge(h, NSPoint(x: P + 8, y: 8))
    }
    cap(String(format: "%02d  %@  %@", s.no, s.scene, label12(s.kind)), h: P)
    img.unlockFocus(); return img
}

