        drawVColumns([a, b, c], in: right)
    }
    cap(String(format: "%02d  %@  %@", s.no, s.scene, label18(s.kind)), h: PH)
    img.unlockFocus(); return img
}

func render12(_ s: S12) -> NSImage {
    let img = NSImage(size: NSSize(width: S, height: P))
    img.lockFocus(); NSColor.black.setFill(); NSRect(x: 0, y: 0, width: S, height: P).fill()
    let left = NSRect(x: 0, y: 0, width: P, height: P)
    let right = NSRect(x: P, y: 0, width: P, height: P)
    switch s.kind {
    case .twin(let a, let b):
        drawPage(a, in: left); drawPage(b, in: right)
        badge(a, NSPoint(x: 8, y: 8)); badge(b, NSPoint(x: P + 8, y: 8))
    case .fourV(let a, let b, let c, let d):
        drawVColumns([a, b], in: left)
        drawVColumns([c, d], in: right)
    case .heroV_twoV(let h, let a, let b):
        drawV(h, in: left)
        drawVColumns([a, b], in: right)
        badge(h, NSPoint(x: 8, y: 8)); badge(a, NSPoint(x: P + 6, y: 8)); badge(b, NSPoint(x: P + P/2 + 6, y: 8))
    case .twoV_heroV(let a, let b, let h):
        drawVColumns([a, b], in: left)
        drawV(h, in: right)
        badge(a, NSPoint(x: 6, y: 8)); badge(b, NSPoint(x: P/2 + 6, y: 8)); badge(h, NSPoint(x: P + 8, y: 8))
    case .heroV_threeV(let h, let a, let b, let c):
        drawV(h, in: left)
        drawVColumns([a, b, c], in: right)
        badge(h, NSPoint(x: 8, y: 8)); badge(a, NSPoint(x: P + 4, y: 8))
        badge(b, NSPoint(x: P + P/3 + 4, y: 8)); badge(c, NSPoint(x: P + 2*P/3 + 4, y: 8))
    case .threeV_heroV(let a, let b, let c, let h):
        drawVColumns([a, b, c], in: left)
        drawV(h, in: right)
        badge(a, NSPoint(x: 4, y: 8)); badge(b, NSPoint(x: P/3 + 4, y: 8))
