func jpg(_ id: String) -> String { SRC + "/" + id + ".jpg" }
func exists(_ id: String) -> Bool { FileManager.default.fileExists(atPath: jpg(id)) }
func loadCG(_ id: String) -> (CGImage, CGFloat, CGFloat)? {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: jpg(id)) as CFURL, nil),
          let cg = CGImageSourceCreateImageAtIndex(src, 0, [kCGImageSourceShouldCache: true] as CFDictionary) else { return nil }
    return (cg, CGFloat(cg.width), CGFloat(cg.height))
}
func isH(_ id: String) -> Bool {
    guard let (_, w, h) = loadCG(id) else { return true }
    return w >= h * 1.05
}
func isV(_ id: String) -> Bool {
    guard let (_, w, h) = loadCG(id) else { return false }
    return h >= w * 1.05
}
func subjectCenter(cg: CGImage) -> (CGFloat, CGFloat) {
    let req = VNDetectFaceRectanglesRequest()
    try? VNImageRequestHandler(cgImage: cg, options: [:]).perform([req])
    let faces = req.results ?? []
    if faces.isEmpty { return (0.5, 0.42) }
    var sx: CGFloat = 0, sy: CGFloat = 0, w: CGFloat = 0
    for f in faces {
        let a = f.boundingBox.width * f.boundingBox.height
        sx += f.boundingBox.midX * a; sy += f.boundingBox.midY * a; w += a
    }
    return (sx / w, sy / w)
}
func saveJPEG(_ img: NSImage, to path: String, q: CGFloat = 0.88) {
    guard let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff),
          let data = rep.representation(using: .jpeg, properties: [.compressionFactor: q]) else { fatalError(path) }
    try! data.write(to: URL(fileURLWithPath: path))
}

func drawIn(_ id: String, dest: NSRect, biasX: CGFloat? = nil, mode: String) {
    guard let (cg, pw, ph) = loadCG(id) else { return }
    let (sx, sy) = subjectCenter(cg: cg)
    let scale: CGFloat
    if mode == "H" {
        precondition(isH(id), "H-slot \(id)")
        precondition(dest.width + 1 >= dest.height * 0.85, "H-slot not landscape/square \(dest)")
        scale = max(dest.width / pw, dest.height / ph)
    } else {
        precondition(isV(id), "V-slot \(id)")
        // 竖槽不得是扁的（宽明显大于高）
        precondition(dest.width <= dest.height * 1.15, "V-slot too wide \(dest) for \(id)")
        if dest.width / dest.height > 0.85 {
            // 方页单图：方裁（保留竖图中心），不是扁裁
            scale = max(dest.width / pw, dest.height / ph)
        } else {
            // 真竖栏：先铺满高度，只裁左右
            scale = dest.height / ph
            if pw * scale < dest.width - 0.5 {
                // 栏比图略宽：略放大铺满，仍以竖为主
                let s2 = dest.width / pw
                // 用 s2 会裁上下；仅当缺口大时才用
                if dest.width - pw * scale > dest.width * 0.12 {
                    // 缺口大则 cover
                    let sc = max(dest.width / pw, dest.height / ph)
                    finish(cg, pw, ph, sx, sy, sc, dest, biasX)
                    return
                }
            }
            finish(cg, pw, ph, sx, sy, scale, dest, biasX)
            return
        }
    }
    finish(cg, pw, ph, sx, sy, scale, dest, biasX)
}

func finish(_ cg: CGImage, _ pw: CGFloat, _ ph: CGFloat, _ sx: CGFloat, _ sy: CGFloat, _ scale: CGFloat, _ dest: NSRect, _ biasX: CGFloat?) {
    let dw = pw * scale, dh = ph * scale
    let tx = biasX ?? dest.midX
    var ox = tx - sx * dw, oy = dest.midY - sy * dh
    ox = min(max(ox, dest.maxX - dw), dest.minX)
    oy = min(max(oy, dest.maxY - dh), dest.minY)
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: dest).addClip()
    NSImage(cgImage: cg, size: NSSize(width: pw, height: ph)).draw(in: NSRect(x: ox, y: oy, width: dw, height: dh), from: .zero, operation: .copy, fraction: 1)
    NSGraphicsContext.current?.cgContext.restoreGState()
}

func drawH(_ id: String, in dest: NSRect, biasX: CGFloat? = nil) { drawIn(id, dest: dest, biasX: biasX, mode: "H") }
func drawV(_ id: String, in dest: NSRect) { drawIn(id, dest: dest, biasX: nil, mode: "V") }
