func stack(_ thumbs: [NSImage], tw: CGFloat, th: CGFloat, path: String) {
    let gap: CGFloat = 10
    let ow = tw + 40, oh = 24 + CGFloat(thumbs.count) * (th + gap)
    let o = NSImage(size: NSSize(width: ow, height: oh))
    o.lockFocus(); NSColor(white: 0.08, alpha: 1).setFill(); NSRect(x:0,y:0,width:ow,height:oh).fill()
    for (i, t) in thumbs.enumerated() {
        let y = oh - 12 - CGFloat(i + 1) * (th + gap) + gap
        t.draw(in: NSRect(x: 20, y: y, width: tw, height: th))
    }
    o.unlockFocus(); saveJPEG(o, to: path, q: 0.82)
}
